// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: a strictly positive deposit that the owner can
        // later withdraw in full. deposit via the payable fallback.
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(this), amount);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertEq(address(c).balance, amount);

        // owner (msg.sender at construction) withdraws everything
        vm.prank(address(this));
        c.withdrawAll();

        // General rule: withdrawAll always empties the contract's balance.
        assertTrue(address(c).balance == 0);
    }
}
